#!/usr/bin/env bash
# Generated by OpenOrchestrate.
# Install the repository hooks without copying them into .git/hooks.
set -euo pipefail

ROOT="$(git rev-parse --show-toplevel)"
cd "$ROOT"

chmod +x .githooks/pre-commit .githooks/pre-push scripts/verify.sh scripts/install-hooks.sh 2>/dev/null || true

current="$(git config --get core.hooksPath || true)"
case "$current" in
  "" | ".githooks" | "./.githooks" | "$ROOT/.githooks") ;;
  *)
    echo "core.hooksPath is already set to $current; leaving it alone." >&2
    case "$current" in
      .husky | .husky/ | .husky/_ | */.husky | */.husky/_ | .husky/*)
        echo "Husky detected. Compose OO verify without replacing husky:" >&2
        echo "  oo hooks compose" >&2
        ;;
      *)
        echo "Merge a call to bash scripts/verify.sh pre-commit into your hook manager." >&2
        echo "OpenOrchestrate will not change a foreign core.hooksPath." >&2
        ;;
    esac
    exit 0
    ;;
esac

git config core.hooksPath .githooks
echo "Installed hooks from .githooks (core.hooksPath=.githooks)."
echo "Run all checks manually with: ./scripts/verify.sh"
echo "Bypass a run with: git commit --no-verify"
